import { ADDED_3, sakuga, youtube } from "@/lib/data/helpers";
import type { BlurbKind, Resource } from "@/lib/types";

/**
 * Third pass (2026-10-28): the "Ref ideas" YouTube playlist and archived key
 * animation found through AnimationReference.org.
 *
 * - YouTube facts (title, channel, date, length, views) come from each watch page
 *   (lib/data/youtube-snapshot.ts). Reels, tutorials and references were checked
 *   against their own descriptions; studio and game names are only given when the
 *   video's title or description states them.
 * - Sakugabooru cuts: title = the work's official title plus the episode/credit
 *   given in the post's source field; creator = the post's artist tags; duration
 *   read from the video file itself. AnimationReference.org's own re-uploads of
 *   films and Instagram clips were skipped: only cuts with a credited artist and a
 *   work tag on Sakugabooru were kept, and each links to its original post.
 * Descriptions of reels and Sakugabooru cuts are generated from these verified
 * fields in every language (lib/data/templates.ts).
 */
type Data = Parameters<typeof youtube>[1];
const third = { kind: "reference" as const, addedAt: ADDED_3 };
const thirdTut = { kind: "tutorial" as const, addedAt: ADDED_3 };

function reel(id: string, blurb: BlurbKind, data: Partial<Omit<Data, "kind" | "addedAt" | "blurb">>): Resource {
  return youtube(id, {
    ...third,
    contentType: "reference",
    media: ["game"],
    categories: ["demo-reels", "game-animation"],
    tags: ["reel"],
    description: "",
    ...data,
    blurb,
  });
}

